14	#include "scoreboard.h"
15	
16	using namespace vortex;
17	
18	Scoreboard::Scoreboard(const SimContext& ctx, const char* name)
19	  : SimObject<Scoreboard>(ctx, name)
20	  , in_use_regs_(VX_CFG_NUM_WARPS) {
21	  for (auto& in_use_reg : in_use_regs_) {
22	    in_use_reg.resize((int)RegType::Count);
23	  }
24	  this->on_reset();
25	}
26	
27	Scoreboard::~Scoreboard() {
28	}
29	
30	void Scoreboard::on_reset() {
31	  for (auto& in_use_reg : in_use_regs_) {
32	    for (auto& mask : in_use_reg) {
33	      mask.reset();
34	    }
35	  }
36	  owners_.clear();
37	  commit_counts_.clear();
38	  pending_reserve_.clear();
39	}
40	
41	bool Scoreboard::in_use(instr_trace_t* trace) const {
42	  if (trace->wb) {
43	    assert(trace->dst_reg.type != RegType::None);
44	    if (in_use_regs_.at(trace->wid).at((int)trace->dst_reg.type).test(trace->dst_reg.idx)) {
45	      return true;
46	    }
47	  }
48	  for (uint32_t i = 0; i < trace->src_regs.size(); ++i) {
49	    if (trace->src_regs[i].type != RegType::None) {
50	      if (in_use_regs_.at(trace->wid).at((int)trace->src_regs[i].type).test(trace->src_regs[i].idx)) {
51	        return true;
52	      }
53	    }
54	  }
55	  return false;
56	}
57	
58	std::vector<Scoreboard::reg_use_t> Scoreboard::get_uses(instr_trace_t* trace) const {
59	  std::vector<reg_use_t> out;
60	  if (trace->wb) {
61	    assert(trace->dst_reg.type != RegType::None);
62	    if (in_use_regs_.at(trace->wid).at((int)trace->dst_reg.type).test(trace->dst_reg.idx)) {
63	      uint32_t reg_id = get_reg_id(trace->dst_reg, trace->wid);
64	      auto owner = owners_.at(reg_id);
65	      out.push_back({trace->dst_reg.type, trace->dst_reg.idx, owner->fu_type, owner->op_type, owner->uuid});
66	    }
67	  }
68	  for (uint32_t i = 0; i < trace->src_regs.size(); ++i) {
69	    if (trace->src_regs[i].type != RegType::None) {
70	      if (in_use_regs_.at(trace->wid).at((int)trace->src_regs[i].type).test(trace->src_regs[i].idx)) {
71	        uint32_t reg_id = get_reg_id(trace->src_regs[i], trace->wid);
72	        auto owner = owners_.at(reg_id);
73	        out.push_back({trace->src_regs[i].type, trace->src_regs[i].idx, owner->fu_type, owner->op_type, owner->uuid});
74	      }
75	    }
76	  }
77	  return out;
78	}
79	
80	void Scoreboard::reserve(instr_trace_t* trace) {
81	  uint32_t reg_id = get_reg_id(trace->dst_reg, trace->wid);
82	  assert(trace->wb);
83	  in_use_regs_.at(trace->wid).at((int)trace->dst_reg.type).set(trace->dst_reg.idx);
84	  assert(owners_.count(reg_id) == 0);
85	  owners_[reg_id] = trace;
86	}
87	
88	void Scoreboard::release(instr_trace_t* trace) {
89	  uint32_t reg_id = get_reg_id(trace->dst_reg, trace->wid);
90	  assert(trace->wb);
91	  assert(in_use_regs_.at(trace->wid).at((int)trace->dst_reg.type).test(trace->dst_reg.idx));
92	  assert(owners_.count(reg_id) != 0);
93	  owners_.erase(reg_id);
94	  commit_counts_.erase(reg_id);
95	  // RTU callback-trap handoff: if a parked WAIT's reservation was deferred
96	  // onto this register (because this op owned it at mret-restore time),
97	  // re-install it now instead of clearing the busy bit — the resumed
98	  // kernel's vx_rt_get_after still needs to stall on it until TERMINAL.
99	  auto pend = pending_reserve_.find(reg_id);
100	  if (pend != pending_reserve_.end()) {
101	    owners_[reg_id] = pend->second;          // busy bit stays set
102	    pending_reserve_.erase(pend);
103	    return;
104	  }
105	  in_use_regs_.at(trace->wid).at((int)trace->dst_reg.type).reset(trace->dst_reg.idx);
106	}
107	
108	std::vector<instr_trace_t*> Scoreboard::snapshot_warp(uint32_t wid) {
109	  std::vector<instr_trace_t*> out;
110	  // Lift only SUSPENDED traces' reservations (the WAIT parked on a pending
111	  // TERMINAL): they hold their dst busy without flowing and cannot release
112	  // until the callback dispatcher runs cb_ret, so the dispatcher's context
113	  // save/restore would deadlock on them. Independent in-flight instructions
114	  // (e.g. a load issued ahead of the parked WAIT) keep their reservations and
115	  // release normally on commit — clearing them here would assert/leak when
116	  // they retire during the trap (rtu_isa_v2 callback path).
117	  for (auto it = owners_.begin(); it != owners_.end(); ) {
118	    instr_trace_t* tr = it->second;
119	    if (tr->wid == wid && tr->suspended) {
120	      out.push_back(tr);
121	      in_use_regs_.at(wid).at((int)tr->dst_reg.type).reset(tr->dst_reg.idx);
122	      commit_counts_.erase(it->first);
123	      it = owners_.erase(it);
124	    } else {
125	      ++it;
126	    }
127	  }
128	  return out;
129	}
130	
131	void Scoreboard::restore_warp(const std::vector<instr_trace_t*>& snapshot) {
132	  for (auto* tr : snapshot) {
133	    uint32_t reg_id = get_reg_id(tr->dst_reg, tr->wid);
134	    if (owners_.count(reg_id) == 0) {
135	      in_use_regs_.at(tr->wid).at((int)tr->dst_reg.type).set(tr->dst_reg.idx);
136	      owners_[reg_id] = tr;
137	    } else {
138	      // A dispatcher writeback currently owns this reg (e.g. the epilogue
139	      // `lw <sts_reg>`). Hand the reservation back when it releases.
140	      pending_reserve_[reg_id] = tr;
141	    }
142	  }
143	}
144	
145	bool Scoreboard::commit_packet(instr_trace_t* trace) {
146	  uint32_t reg_id = get_reg_id(trace->dst_reg, trace->wid);
147	  auto& n = commit_counts_[reg_id];
148	  ++n;
149	  if (n >= trace->num_pkts) {
150	    // All packets committed; release() will erase the counter entry.
151	    return true;
152	  }
153	  return false;
154	}
