15	#include "core.h"
16	#include <iostream>
17	#include <iomanip>
18	#include <simobject.h>
19	
20	using namespace vortex;
21	
22	// wid → local slot index inside this OpcUnit.
23	inline static constexpr uint32_t wid_to_opc_slot(uint32_t wid) {
24	  return (wid / VX_CFG_ISSUE_WIDTH) / VX_CFG_NUM_OPCS;
25	}
26	
27	void OpcUnit::warp_regs_t::reset() {
28	  for (auto& bank : ireg_file) {
29	    for (auto& v : bank) v = 0;
30	  }
31	  for (auto& bank : freg_file) {
32	    for (auto& v : bank) v = 0;
33	  }
34	}
35	
36	OpcUnit::OpcUnit(const SimContext &ctx, const char* name,
37	                 uint32_t num_warp_slots, uint32_t num_threads)
38	  : SimObject<OpcUnit>(ctx, name)
39	  , Input(this)
40	  , Output(this)
41	  , num_threads_(num_threads) {
42	  regs_.reserve(num_warp_slots);
43	  for (uint32_t i = 0; i < num_warp_slots; ++i) {
44	    regs_.emplace_back(num_threads);
45	  }
46	  this->on_reset();
47	}
48	
49	OpcUnit::~OpcUnit() {}
50	
51	void OpcUnit::on_reset() {
52	  total_stalls_ = 0;
53	  cur_trace_ = nullptr;
54	  release_cycle_ = 0;
55	  for (auto& w : regs_) {
56	    w.reset();
57	  }
58	}
59	
60	static uint32_t compute_bank_conflicts(const instr_trace_t* trace) {
61	  uint32_t stalls = 0;
62	  for (uint32_t i = 0; i < NUM_SRC_REGS; ++i) {
63	    for (uint32_t j = i + 1; j < NUM_SRC_REGS; ++j) {
64	      if ((trace->src_regs[i].type == RegType::None)
65	       || (trace->src_regs[j].type == RegType::None))
66	        continue;
67	      if ((trace->src_regs[i].type == RegType::Integer && trace->src_regs[i].id() == 0)
68	       || (trace->src_regs[j].type == RegType::Integer && trace->src_regs[j].id() == 0))
69	        continue; // skip x0
70	      uint32_t bank_i = trace->src_regs[i].idx % VX_CFG_NUM_GPR_BANKS;
71	      uint32_t bank_j = trace->src_regs[j].idx % VX_CFG_NUM_GPR_BANKS;
72	      if (bank_i == bank_j)
73	        ++stalls;
74	    }
75	  }
76	  return stalls;
77	}
78	
79	void OpcUnit::on_tick() {
80	  auto cur_cycle = SimPlatform::instance().cycles();
81	
82	  // forward held uop once its collection phase has elapsed
83	  if (cur_trace_ != nullptr && cur_cycle >= release_cycle_) {
84	    if (!Output.try_send(cur_trace_, 1))
85	      return;
86	    DT(3, this->name() << "-pipeline operands: " << *cur_trace_);
87	    cur_trace_ = nullptr;
88	  }
89	
90	  // accept next uop into the holding slot
91	  if (cur_trace_ == nullptr && !Input.empty()) {
92	    auto trace = Input.peek();
93	    uint32_t stalls = compute_bank_conflicts(trace);
94	    total_stalls_ += stalls;
95	    cur_trace_ = trace;
96	    release_cycle_ = cur_cycle + 1 + stalls;
97	    Input.pop();
98	  }
99	}
100	
101	void OpcUnit::read_src(std::vector<reg_data_t>& out,
102	                       uint32_t wid,
103	                       uint32_t src_index,
104	                       const RegOpd& reg) const {
105	  __unused(src_index);
106	  const auto& slot = regs_[wid_to_opc_slot(wid)];
107	  switch (reg.type) {
108	  case RegType::Integer: {
109	    const auto& src = slot.ireg_file[reg.idx];
110	    for (uint32_t t = 0; t < num_threads_; ++t) {
111	      out[t].u = src[t];
112	    }
113	  } break;
114	  case RegType::Float: {
115	    const auto& src = slot.freg_file[reg.idx];
116	    for (uint32_t t = 0; t < num_threads_; ++t) {
117	      out[t].u64 = src[t];
118	    }
119	  } break;
120	  case RegType::None:
121	    break;
122	  default:
123	    std::abort();
124	  }
125	}
126	
127	// Expand an 8-bit bytesel mask into a per-byte 64-bit mask:
128	// each set bit i in `bs` produces 0xFF in byte i of the result.
129	static inline uint64_t expand_bytesel64(uint8_t bs) {
130	  uint64_t m = 0;
131	  for (uint32_t b = 0; b < 8; ++b) {
132	    if (bs & (1u << b)) m |= 0xFFull << (8 * b);
133	  }
134	  return m;
135	}
136	
137	void OpcUnit::writeback(instr_trace_t* trace, uint32_t wid) {
138	  if (trace->dst_data.empty())
139	    return;
140	  uint32_t warp_slot = wid_to_opc_slot(wid);
141	  auto& rdest = trace->dst_reg;
142	  auto num_threads = num_threads_;
143	  // Bytesel: 0xFF (default) collapses to full overwrite. Partial-width writers
144	  // (packLD uops) supply a sub-mask so we OR-merge into the regfile slot.
145	  uint64_t mask = expand_bytesel64(trace->dst_bytesel);
146	  switch (rdest.type) {
147	  case RegType::None:
148	    break;
149	  case RegType::Integer: {
150	    auto& bank = regs_.at(warp_slot).ireg_file.at(rdest.idx);
151	    DPH(2, "Dest Reg: " << rdest << "={");
152	    for (uint32_t t = 0; t < num_threads; ++t) {
153	      if (t) DPN(2, ", ");
154	      if (!trace->tmask.test(t)) {
155	        DPN(2, "-");
156	        continue;
157	      }
158	      Word cur = bank.at(t);
159	      Word incoming = trace->dst_data[t].i;
160	      bank.at(t) = (cur & ~Word(mask)) | (incoming & Word(mask));
161	      DPN(2, "0x" << std::hex << trace->dst_data[t].u << std::dec);
162	    }
163	    DPN(2, "} (#" << std::dec << trace->uuid << ")" << std::endl);
164	  } break;
165	  case RegType::Float: {
166	    auto& bank = regs_.at(warp_slot).freg_file.at(rdest.idx);
167	    DPH(2, "Dest Reg: " << rdest << "={");
168	    for (uint32_t t = 0; t < num_threads; ++t) {
169	      if (t) DPN(2, ", ");
170	      if (!trace->tmask.test(t)) {
171	        DPN(2, "-");
172	        continue;
173	      }
174	      uint64_t cur = bank.at(t);
175	      uint64_t incoming = trace->dst_data[t].u64;
176	      bank.at(t) = (cur & ~mask) | (incoming & mask);
177	      if ((bank.at(t) >> 32) == 0xffffffff) {
178	        DPN(2, "0x" << std::hex << uint32_t(bank.at(t)) << std::dec);
179	      } else {
180	        DPN(2, "0x" << std::hex << bank.at(t) << std::dec);
181	      }
182	    }
183	    DPN(2, "} (#" << std::dec << trace->uuid << ")" << std::endl);
184	  } break;
185	  default:
186	    std::cout << "Unrecognized register write back type: " << rdest.type << std::endl;
187	    std::abort();
188	    break;
189	  }
190	}
