26	struct instr_trace_t {
27	public:
28	  const uint64_t uuid;
29	
30	  uint32_t    cid;
31	  uint32_t    wid;
32	  uint32_t    cta_id;
33	  ThreadMask  tmask;
34	  Word        PC;
35	  uint32_t    code;
36	  bool        wb;
37	  // Trap epoch snapshot at schedule time. flush_warp_pipeline bumps
38	  // the warp's epoch on async-trap entry; advance_pc skips stale
39	  // post-fetch traces whose epoch trails the warp's current value so
40	  // they cannot over-advance warp.PC past the trap-set mtvec.
41	  uint32_t    trap_epoch = 0;
42	
43	  RegOpd      dst_reg;
44	
45	  std::vector<RegOpd> src_regs;
46	
47	  FUType     fu_type;
48	
49	  OpType     op_type;
50	
51	  // Operands data
52	  std::vector<std::vector<reg_data_t>> src_data;
53	
54	  // Destination data
55	  std::vector<reg_data_t> dst_data;
56	
57	  // Byte write enable
58	  uint8_t dst_bytesel;
59	
60	  std::shared_ptr<Instr> instr_ptr;
61	
62	  int  pid;
63	  bool sop;
64	  bool eop;
65	
66	  // Total SIMD-split packets for this warp instruction. Commit defers
67	  // scoreboard release until all packets' writebacks have applied, preventing
68	  // out-of-order cache responses from releasing the destination prematurely.
69	  uint32_t num_pkts;
70	
71	  bool fetch_stall;
72	
73	  // Set by a func-unit when a fetch_stall instruction has resolved; the warp
74	  // is released when the trace drains from the FU output (commit fan-in).
75	  bool resume_warp;
76	
77	  // Set while a trace is parked inside a func-unit (the RTU WAIT blocked on a
78	  // pending TERMINAL) and so holds its scoreboard reservation without flowing.
79	  // An async callback trap lifts only suspended traces' reservations (they
80	  // cannot self-release until the dispatcher runs); independent in-flight
81	  // instructions keep theirs and release normally on commit.
82	  bool suspended;
83	
84	  uint64_t issue_time ;
85	
86	  instr_trace_t(uint64_t uuid)
87	    : uuid(uuid)
88	    , cid(0)
89	    , wid(0)
90	    , cta_id(0)
91	    , tmask(0)
92	    , PC(0)
93	    , code(0)
94	    , wb(false)
95	    , dst_reg({RegType::None, 0})
96	    , src_regs(NUM_SRC_REGS, {RegType::None, 0})
97	    , fu_type(FUType::ALU)
98	    , op_type({})
99	     , src_data(NUM_SRC_REGS, std::vector<reg_data_t>(VX_CFG_NUM_THREADS))
100	    , dst_data(VX_CFG_NUM_THREADS)
101	    , dst_bytesel(0xFF)
102	    , pid(-1)
103	    , sop(true)
104	    , eop(true)
105	    , num_pkts(1)
106	    , fetch_stall(false)
107	    , resume_warp(false)
108	    , suspended(false)
109	    , issue_time(SimPlatform::instance().cycles())
110	    , log_once_(false)
111	  {}
112	
113	  instr_trace_t(const instr_trace_t& rhs)
114	    : uuid(rhs.uuid)
115	    , cid(rhs.cid)
116	    , wid(rhs.wid)
117	    , cta_id(rhs.cta_id)
118	    , tmask(rhs.tmask)
119	    , PC(rhs.PC)
120	    , code(rhs.code)
121	    , wb(rhs.wb)
122	    , dst_reg(rhs.dst_reg)
123	    , src_regs(rhs.src_regs)
124	    , fu_type(rhs.fu_type)
125	    , op_type(rhs.op_type)
126	    , src_data(rhs.src_data)
127	    , dst_data(rhs.dst_data)
128	    , dst_bytesel(rhs.dst_bytesel)
129	    , instr_ptr(rhs.instr_ptr)
130	    , pid(rhs.pid)
131	    , sop(rhs.sop)
132	    , eop(rhs.eop)
133	    , num_pkts(rhs.num_pkts)
134	    , fetch_stall(rhs.fetch_stall)
135	    , resume_warp(rhs.resume_warp)
136	    , suspended(rhs.suspended)
137	    , issue_time(rhs.issue_time)
138	    , log_once_(false)
139	  {}
140	
141	  ~instr_trace_t() {}
142	
143	  bool log_once(bool enable) {
144	    bool old = log_once_;
145	    log_once_ = enable;
146	    return old;
147	  }
148	
149	  friend std::ostream &operator<<(std::ostream &os, const instr_trace_t& trace) {
150	    os << "cid=" << trace.cid;
151	    os << ", wid=" << trace.wid;
152	    os << ", cta_id=" << trace.cta_id;
153	    os << ", tmask=";
154	    for (uint32_t i = 0, n = VX_CFG_NUM_THREADS; i < n; ++i) {
155	      os << trace.tmask.test(i);
156	    }
157	    os << ", PC=0x" << std::hex << trace.PC << std::dec;
158	    os << ", wb=" << trace.wb;
159	    if (trace.dst_reg.type != RegType::None) {
160	      os << ", rd=" << trace.dst_reg;
161	    }
162	    for (uint32_t i = 0; i < trace.src_regs.size(); ++i) {
163	      if (trace.src_regs[i].type != RegType::None) {
164	        os << ", rs" << i << "=" << trace.src_regs[i];
165	      }
166	    }
167	    os << ", ex=" << trace.fu_type;
168	    if (trace.pid != -1) {
169	      os << ", pid=" << trace.pid;
170	      os << ", sop=" << trace.sop;
171	      os << ", eop=" << trace.eop;
172	    }
173	    os << " (#" << trace.uuid << ")";
174	    return os;
175	  }
176	
177	private:
178	  bool log_once_;
179	};
