#pragma once

#include <memory>
#include <iostream>
#include <util.h>
#include "types.h"
#include "debug.h"
#include "instr.h"

namespace vortex {

struct instr_trace_t {
public:
  const uint64_t uuid;

  uint32_t    cid;
  uint32_t    wid;
  uint32_t    cta_id;
  ThreadMask  tmask;
  Word        PC;
  uint32_t    code;
  bool        wb;
  // Trap epoch snapshot at schedule time. flush_warp_pipeline bumps
  // the warp's epoch on async-trap entry; advance_pc skips stale
  // post-fetch traces whose epoch trails the warp's current value so
  // they cannot over-advance warp.PC past the trap-set mtvec.
  uint32_t    trap_epoch = 0;

  RegOpd      dst_reg;

  std::vector<RegOpd> src_regs;

  FUType     fu_type;

  OpType     op_type;

  // Operands data
  std::vector<std::vector<reg_data_t>> src_data;

  // Destination data
  std::vector<reg_data_t> dst_data;

  // Byte write enable
  uint8_t dst_bytesel;

  std::shared_ptr<Instr> instr_ptr;

  int  pid;
  bool sop;
  bool eop;

  // Total SIMD-split packets for this warp instruction. Commit defers
  // scoreboard release until all packets' writebacks have applied, preventing
  // out-of-order cache responses from releasing the destination prematurely.
  uint32_t num_pkts;

  bool fetch_stall;

  // Set by a func-unit when a fetch_stall instruction has resolved; the warp
  // is released when the trace drains from the FU output (commit fan-in).
  bool resume_warp;

  // Set while a trace is parked inside a func-unit (the RTU WAIT blocked on a
  // pending TERMINAL) and so holds its scoreboard reservation without flowing.
  // An async callback trap lifts only suspended traces' reservations (they
  // cannot self-release until the dispatcher runs); independent in-flight
  // instructions keep theirs and release normally on commit.
  bool suspended;

  uint64_t issue_time ;

  instr_trace_t(uint64_t uuid)
    : uuid(uuid)
    , cid(0)
    , wid(0)
    , cta_id(0)
    , tmask(0)
    , PC(0)
    , code(0)
    , wb(false)
    , dst_reg({RegType::None, 0})
    , src_regs(NUM_SRC_REGS, {RegType::None, 0})
    , fu_type(FUType::ALU)
    , op_type({})
     , src_data(NUM_SRC_REGS, std::vector<reg_data_t>(VX_CFG_NUM_THREADS))
    , dst_data(VX_CFG_NUM_THREADS)
    , dst_bytesel(0xFF)
    , pid(-1)
    , sop(true)
    , eop(true)
    , num_pkts(1)
    , fetch_stall(false)
    , resume_warp(false)
    , suspended(false)
    , issue_time(SimPlatform::instance().cycles())
    , log_once_(false)
  {}

  instr_trace_t(const instr_trace_t& rhs)
    : uuid(rhs.uuid)
    , cid(rhs.cid)
    , wid(rhs.wid)
    , cta_id(rhs.cta_id)
    , tmask(rhs.tmask)
    , PC(rhs.PC)
    , code(rhs.code)
    , wb(rhs.wb)
    , dst_reg(rhs.dst_reg)
    , src_regs(rhs.src_regs)
    , fu_type(rhs.fu_type)
    , op_type(rhs.op_type)
    , src_data(rhs.src_data)
    , dst_data(rhs.dst_data)
    , dst_bytesel(rhs.dst_bytesel)
    , instr_ptr(rhs.instr_ptr)
    , pid(rhs.pid)
    , sop(rhs.sop)
    , eop(rhs.eop)
    , num_pkts(rhs.num_pkts)
    , fetch_stall(rhs.fetch_stall)
    , resume_warp(rhs.resume_warp)
    , suspended(rhs.suspended)
    , issue_time(rhs.issue_time)
    , log_once_(false)
  {}

  ~instr_trace_t() {}

  bool log_once(bool enable) {
    bool old = log_once_;
    log_once_ = enable;
    return old;
  }

  friend std::ostream &operator<<(std::ostream &os, const instr_trace_t& trace) {
    os << "cid=" << trace.cid;
    os << ", wid=" << trace.wid;
    os << ", cta_id=" << trace.cta_id;
    os << ", tmask=";
    for (uint32_t i = 0, n = VX_CFG_NUM_THREADS; i < n; ++i) {
      os << trace.tmask.test(i);
    }
    os << ", PC=0x" << std::hex << trace.PC << std::dec;
    os << ", wb=" << trace.wb;
    if (trace.dst_reg.type != RegType::None) {
      os << ", rd=" << trace.dst_reg;
    }
    for (uint32_t i = 0; i < trace.src_regs.size(); ++i) {
      if (trace.src_regs[i].type != RegType::None) {
        os << ", rs" << i << "=" << trace.src_regs[i];
      }
    }
    os << ", ex=" << trace.fu_type;
    if (trace.pid != -1) {
      os << ", pid=" << trace.pid;
      os << ", sop=" << trace.sop;
      os << ", eop=" << trace.eop;
    }
    os << " (#" << trace.uuid << ")";
    return os;
  }

private:
  bool log_once_;
};

using TraceArbiter = TxArbiter<instr_trace_t*>;

}

