477	    // instruction commits. Default to releasing every stalling instruction;
478	    // warp-control (SFU) refines this for ops whose warp is instead released by
479	    // the barrier/spawn machinery (see SfuUnit::on_tick).
480	    trace->resume_warp = trace->fetch_stall;
