483	    // 4 bytes otherwise). Branch/JAL/JALR commit later overrides warp.PC
484	    // with the resolved target.
485	    {
486	      bool is_rvc = (trace->code & 0x3u) != 0x3u;
487	      scheduler_->advance_pc(trace, is_rvc ? 2 : 4);
488	    }
