  for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
    snprintf(sname, 100, "%s-commit-arb%d", name.c_str(), iw);
    commit_arbs_.at(iw) = TraceArbiter::Create(sname, ArbiterType::RoundRobin, (uint32_t)FUType::Count, 1);
  }

