}

void reset() {
  for (auto& arb : ibuffer_arbs_) {
    arb.reset();
  }
  for (auto& fc : fu_credits_) {
    std::fill(fc.begin(), fc.end(), 0);
  }

  pending_instrs_.clear();
  pending_ifetches_ = 0;

  std::fill(ibuf_inflight_.begin(), ibuf_inflight_.end(), 0);

